import assert from "node:assert/strict";
import test from "node:test";
import { analyzeClaim } from "../src/lib/claim-analysis.ts";
import { identifyIngredient } from "../src/lib/matching.ts";
import { taxa } from "../src/lib/catalog.ts";
import { retrieveEvidence } from "../src/lib/research-retrieval.ts";

// Expected directions derive from the source results, not labels generated by the engine.
const cases = [
  { claim: "Ewuro reduces blood sugar", source: "bitter-leaf-human-glucose", relation: "contradicts" },
  { claim: "Vernonia amygdalina lowers blood glucose in rats", source: "bitter-leaf-rat-glucose", relation: "supports" },
  { claim: "Bitter leaf lowers blood sugar in people", source: "bitter-leaf-rat-glucose", relation: "does-not-answer" },
  { claim: "Bitter leaf decreases glucose", source: "southwest-diabetes-survey", relation: "partially-addresses" },
  { claim: "Azadirachta indica reduces HbA1c", source: "neem-human-glucose", relation: "supports" },
  { claim: "Neem always cures diabetes", source: "neem-human-glucose", relation: "partially-addresses" },
  { claim: "Neem seed oil lowers blood sugar", source: "neem-human-glucose", relation: "does-not-answer" },
  { claim: "Neem alone lowers blood sugar", source: "neem-human-glucose", relation: "does-not-answer" },
  { claim: "Homemade neem tea lowers blood glucose", source: "neem-human-glucose", relation: "does-not-answer" },
  { claim: "Carica papaya increases platelet count", source: "papaya-human-platelets", relation: "supports" },
  { claim: "Papaya decreases platelets", source: "papaya-human-platelets", relation: "contradicts" },
  { claim: "Papaya fruit increases platelets", source: "papaya-human-platelets", relation: "does-not-answer" },
  { claim: "Ginger speeds gastric emptying", source: "ginger-emptying-wu", relation: "supports" },
  { claim: "Ginger speeds gastric emptying", source: "ginger-emptying-phillips", relation: "contradicts" },
  { claim: "Hibiscus reduces blood pressure", source: "roselle-blood-pressure", relation: "supports" },
] as const;

test("source-derived claim relations preserve study conditions and conflicting outcomes", () => {
  for (const row of cases) {
    const answer = analyzeClaim(row.claim);
    assert.equal(answer.records.find(({ record }) => record.id === row.source)?.relation, row.relation, row.claim);
  }
  console.log(`Claim relations: ${cases.length}/${cases.length} source-derived expected outcomes. Developer-authored evaluation, specialist review pending.`);
});

test("claim analysis abstains on missing names, unknown outcomes, ambiguity and personal requests", () => {
  for (const claim of ["Turmeric lowers blood sugar", "Cinnamon lowers blood sugar", "Neem cures cancer", "Should I take neem for my diabetes?", "Bitter leaf reduces blood sugar and blood pressure"]) {
    assert.equal(analyzeClaim(claim).records.length, 0, claim);
  }
  const publicHealth = analyzeClaim("Guava cures cholera");
  assert.deepEqual(publicHealth.records.map(({ record }) => record.id), ["ncdc-cholera-2024"]);
  assert.deepEqual(retrieveEvidence("guava cholera").records.map(({ id }) => id), ["ncdc-cholera-2024"]);
  assert.equal(retrieveEvidence("What are the safety concerns?").records.length, 0);
});

test("new taxonomic synonyms and sourced local names reuse the existing matcher", () => {
  for (const [name, id] of [["Gymnanthemum amygdalinum", "bitter-leaf"], ["Vernonia amygdalina", "bitter-leaf"], ["Onugbu", "bitter-leaf"], ["Dogon yaro", "neem"], ["Ibepe", "papaya"]]) {
    assert.equal(identifyIngredient(name, taxa).candidates[0]?.id, id);
  }
  assert.equal(identifyIngredient("Ewuro", taxa).kind, "alias");
});
